 initial_equal={n:{k:bool(np.array_equal(z[k],initial[spec['cell_order'][0]][k])) for k in z} for n,z in initial.items()};assert all(all(v.values()) for v in initial_equal.values());ledger=hashlib.sha256((ROOT/'results/S1_API_LEDGER.jsonl').read_bytes()).hexdigest();assert ledger=='d9888b711a5340bbd21ec4d1bb6891423a2d300a67736f79bb99fb9062dd3290'
